import http from 'k6/http';
import { check, sleep } from 'k6';
import { BASE_URL, TITLE_ID, headers, defaultStages, defaultThresholds } from './config.js';

export const options = { stages: defaultStages, thresholds: defaultThresholds };

// Playback authorization: creates a playback session and checks that a short-lived
// manifest URL comes back. The manifest itself is served by R2/CDN and is NOT fetched
// here, so no video bytes are generated by this test. The URL is never logged.
export default function () {
  const body = JSON.stringify({
    contentId: TITLE_ID,
    targetType: 'MOVIE',
    deviceId: `k6-device-${__VU}`,
  });

  const res = http.post(`${BASE_URL}/api/v1/streaming/sessions`, body, { headers: headers() });

  check(res, {
    'session created (201)': (r) => r.status === 201,
    'has manifestUrl': (r) => r.status === 201 && !!r.json('manifestUrl'),
    'has expiresAt': (r) => r.status === 201 && !!r.json('expiresAt'),
  });

  sleep(2);
}
